 __global__ void copy_factor_lower_kernel(
         const float* factor, float* output, int leading_output) {
     constexpr int tile_size = 32;
     __shared__ float tile[tile_size][tile_size + 1];

     const int linear = static_cast<int>(blockIdx.x);
     int tile_row = static_cast<int>(
         (sqrtf(8.0f * static_cast<float>(linear) + 1.0f) - 1.0f) * 0.5f
     );
     int triangular_base = tile_row * (tile_row + 1) / 2;
     if (triangular_base > linear) {
         --tile_row;
         triangular_base = tile_row * (tile_row + 1) / 2;
     }
     while (triangular_base + tile_row + 1 <= linear) {
         triangular_base += tile_row + 1;
         ++tile_row;
     }
     const int tile_col = linear - triangular_base;
     const int tx = threadIdx.x;
     const int row_base = tile_row * tile_size;
     const int col_base = tile_col * tile_size;
     for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
         tile[y][tx] = factor[
             row_base + tx + static_cast<int64_t>(col_base + y) * 4096
         ];
     }
     __syncthreads();
     for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
         const int row = row_base + y;
         const int col = col_base + tx;
         output[static_cast<int64_t>(row) * leading_output + col] =
             row >= col ? tile[tx][y] : 0.0f;
     }

     if (tile_row > tile_col && (tile_row >> 3) == (tile_col >> 3)) {
         const int upper_row_base = col_base;
         const int upper_col_base = row_base;
         for (int y = threadIdx.y; y < tile_size; y += blockDim.y) {
             output[
                 static_cast<int64_t>(upper_row_base + y) * leading_output
                 + upper_col_base + tx
             ] = 0.0f;
         }
     }
 }

