def _blocked_cholesky(data: torch.Tensor, output: torch.Tensor) -> torch.Tensor:
    if output.shape[0] == 1:
        _ext.lower_copy_(data, output)
    else:
        output.copy_(data)
    n = output.shape[-1]
    if output.shape[0] == 1:
        block = 4096
    elif n == 1024:
        block = 256
    else:
        block = 128

    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        torch.backends.cuda.matmul.allow_tf32 = True
        for k in range(0, n, block):
            stop = min(k + block, n)
            diagonal = output[:, k:stop, k:stop]
            if output.shape[0] == 1:
                factor = torch.linalg.cholesky_ex(
                    diagonal,
                    check_errors=False,
                    out=(_factor_workspace, _factor_info),
                ).L
            else:
                factor = torch.linalg.cholesky_ex(
                    diagonal, check_errors=False
                ).L
            if output.shape[0] == 1:
                _ext.copy_factor_lower_(factor, diagonal)
            else:
                diagonal.copy_(factor)
            if stop == n:
                continue

            panel = output[:, stop:, k:stop]
            if output.shape[0] == 1:
                _ext.trsm_(factor, panel)
                half_panel = _half_workspace[: panel.shape[1]]
                _ext.convert_panel_(panel[0], half_panel)
                _triangular_rankk_(
                    output[0, stop:, stop:], half_panel
                )
            else:
                solved = torch.linalg.solve_triangular(
                    factor,
                    panel.transpose(-2, -1),
                    upper=False,
                ).transpose(-2, -1)
                panel.copy_(solved)
                _ext.fp16_update_(
                    output[:, stop:, stop:], solved.to(torch.float16)
                )
    finally:
        torch.backends.cuda.matmul.allow_tf32 = old_tf32

    if output.shape[0] == 1:
        return output
    return output.tril_()


def _high_batch_1024_cholesky(
    data: torch.Tensor, output: torch.Tensor
) -> torch.Tensor:
    global _batch_half_panel, _batch_trsm_pointers
    global _batch_factor_workspace, _batch_factor_info
    _ext.batch_lower_copy_cuda(data, output)
    n = output.shape[-1]
    block = 256
    half_shape = (output.shape[0], n - block, block)
    if _batch_half_panel is None or _batch_half_panel.shape != half_shape:
        _batch_half_panel = torch.empty(
            half_shape, device=output.device, dtype=torch.float16
        )
    pointer_count = 2 * output.shape[0]
    if (
        _batch_trsm_pointers is None
        or _batch_trsm_pointers.numel() != pointer_count
    ):
        _batch_trsm_pointers = torch.empty(
            pointer_count, device=output.device, dtype=torch.int64
        )

    old_tf32 = torch.backends.cuda.matmul.allow_tf32
    try:
        torch.backends.cuda.matmul.allow_tf32 = True
        for k in range(0, n, block):
            stop = k + block
            diagonal = output[:, k:stop, k:stop]
            factor = torch.linalg.cholesky_ex(
                diagonal,
                check_errors=False,
                out=(_batch_factor_workspace, _batch_factor_info),
            ).L
            panel = output[:, stop:, k:stop]
            if stop == n:
                _ext.prepare_batch_factor_and_pointers_cuda(
                    factor, diagonal, panel, _batch_trsm_pointers
                )
                continue
            converted = _batch_half_panel[:, : n - stop]
            _ext.batch_panel_step_(
                factor,
                diagonal,
                panel,
                converted,
                output[:, stop:, stop:],
                _batch_trsm_pointers,
            )
    finally:
        torch.backends.cuda.matmul.allow_tf32 = old_tf32
    return output.tril_()


